package launchpad

import (
	ufmt "gno.land/p/nt/ufmt/v0"
	"gno.land/r/gnoswap/launchpad"
)

// assertIsDepositOwner asserts that the caller is the owner of the deposit.
// Panics if the caller is not the owner of the deposit.
func (lp *launchpadV1) assertIsDepositOwner(depositID string, caller address) {
	deposit, err := lp.getDeposit(depositID)
	if err != nil {
		panic(err.Error())
	}

	if !deposit.IsDepositor(caller) {
		panic(makeErrorWithDetails(errInvalidOwner, ufmt.Sprintf("(%s)", caller.String())).Error())
	}
}

// assertIsValidAmount panics if the amount is zero.
func assertIsValidAmount(amount int64) {
	if amount < minimumDepositAmount {
		panic(makeErrorWithDetails(
			errInvalidAmount,
			ufmt.Sprintf("amount(%d) should greater than minimum deposit amount(%d)", amount, minimumDepositAmount),
		))
	}

	if (amount % minimumDepositAmount) != 0 {
		panic(makeErrorWithDetails(
			errInvalidAmount,
			ufmt.Sprintf("amount(%d) must be a multiple of 1_000_000", amount),
		))
	}
}

// assertIsDepositNotWithdrawn asserts that the deposit is not withdrawn.
func assertIsDepositNotWithdrawn(deposit launchpad.Deposit) {
	if deposit.IsWithdrawn() {
		panic(makeErrorWithDetails(errAlreadyCollected, ufmt.Sprintf("(%s)", deposit.ID())))
	}
}

// assertIsDepositEnded asserts that the deposit is ended.
func assertIsDepositEnded(deposit launchpad.Deposit, currentTime int64) {
	if !deposit.IsEnded(currentTime) {
		panic(makeErrorWithDetails(errNotYetEndedProject, ufmt.Sprintf("(%s)", deposit.ID())))
	}
}

// assertHasTierReward asserts that the tier has rewards to distribute.
// A zero-rate tier cannot settle rewards, which would lock withdrawals.
func assertHasTierReward(tier *launchpad.ProjectTier) {
	if tier.DistributeAmountPerSecondX128().IsZero() {
		panic(makeErrorWithDetails(errNoLeftReward, ufmt.Sprintf("(%s)", tier.ID())))
	}
}

// assertHasProject asserts that the caller is the owner of at least one project.
// Panics if the caller is not the owner of any project.
func (lp *launchpadV1) assertHasProject(caller address) {
	if !lp.store.GetProjectRecipients().Has(caller.String()) {
		panic(makeErrorWithDetails(
			errInvalidOwner,
			ufmt.Sprintf("caller %s is not the owner of any project", caller.String()),
		))
	}
}

func assertNotImplementYet() {
	panic("NotImplementYet")
}

package launchpad

const (
	projectTier30  = int64(30)
	projectTier90  = int64(90)
	projectTier180 = int64(180)

	dayTime = int64(24 * 60 * 60) // 86400

	minimumDepositAmount = int64(1_000_000)

	stringSplitterPad = "*PAD*"

	maxProjectConditionCount = 5

	projectMinimumStartDelayTime = dayTime * 3 // 3 days
)

// contract paths
const (
	GOV_XGNS_PATH string = "gno.land/r/gnoswap/gov/xgns"
	GNS_TOKEN_KEY string = "gno.land/r/gnoswap/gns.GNS"
)

// MUST BE IMMUTABLE, DO NOT MODIFY.
var projectTierDurations = []int64{
	projectTier30,
	projectTier90,
	projectTier180,
}

// MUST BE IMMUTABLE, DO NOT MODIFY.
var projectTierDurationTimes = map[int64]int64{
	projectTier30:  dayTime * projectTier30,  // 30 days
	projectTier90:  dayTime * projectTier90,  // 90 days
	projectTier180: dayTime * projectTier180, // 180 days
}

// MUST BE IMMUTABLE, DO NOT MODIFY.
var projectTierRewardCollectableDuration = map[int64]int64{
	projectTier30:  dayTime * 1, // 1 days
	projectTier90:  dayTime * 1, // 1 days
	projectTier180: dayTime * 1, // 1 days
}

package launchpad

import (
	"chain"

	"gno.land/p/gnoswap/utils/v1"
	"gno.land/r/gnoswap/launchpad"
)

// emitUpdateLaunchpadRewardAccumulation emits the persisted per-tier reward
// accumulation state so that off-chain indexers can consume the authoritative
// accumulator instead of re-deriving it. It must be emitted after every path that
// calls updateRewardPerDepositX128 (deposit/withdraw/collect/admin-reclaim),
// otherwise the off-chain accumulator drifts from the contract.
//
// The reward manager is keyed by projectTierId, so it is included to identify which
// tier's accumulator this update belongs to. totalDepositAmount is the current tier
// deposit total after the stake change (the divisor for the next accumulation delta),
// and distributeAmountPerSecondX128 lets indexers project the accumulator forward.
func emitUpdateLaunchpadRewardAccumulation(projectTierID string, r *launchpad.RewardManager, totalDepositAmount int64) {
	chain.Emit(
		"UpdateLaunchpadRewardAccumulation",
		"projectTierId", projectTierID,
		"totalDepositAmount", utils.FormatInt(totalDepositAmount),
		"accumulatedRewardPerDepositX128", r.AccumulatedRewardPerDepositX128().ToString(),
		"distributeAmountPerSecondX128", r.DistributeAmountPerSecondX128().ToString(),
		"accumulatedTime", utils.FormatInt(r.AccumulatedTime()),
	)
}

package launchpad

import (
	"errors"
	"time"

	rotree "gno.land/p/nt/bptree/rotree/v0"
	ufmt "gno.land/p/nt/ufmt/v0"

	"gno.land/p/gnoswap/uint256/v1"
	"gno.land/r/gnoswap/launchpad"
)

// GetProjects returns a read-only view of every project, keyed by project ID.
//
// Returns:
//   - projects: read-only tree keyed by project ID; project entries are cloned before being exposed.
func (lp *launchpadV1) GetProjects() *rotree.ReadOnlyTree {
	return rotree.Wrap(lp.store.GetProjects(), cloneProjectEntry)
}

// GetProjectName returns the name of a project by its ID.
// Returns empty string and error if project not found.
//
// Parameters:
//   - projectId: unique launchpad project identifier to look up.
//
// Returns:
//   - name: configured project name; empty when the project is absent.
//   - err: nil when found; non-nil when projectId is not present in state.
func (lp *launchpadV1) GetProjectName(projectId string) (string, error) {
	project, err := lp.getProject(projectId)
	if err != nil {
		return "", err
	}

	return project.Name(), nil
}

// GetProjectTokenPath returns the token path of a project by its ID.
// Returns empty string and error if project not found.
//
// Parameters:
//   - projectId: unique launchpad project identifier to look up.
//
// Returns:
//   - tokenPath: reward-token contract path configured for the project; empty when absent.
//   - err: nil when found; non-nil when projectId is not present in state.
func (lp *launchpadV1) GetProjectTokenPath(projectId string) (string, error) {
	project, err := lp.getProject(projectId)
	if err != nil {
		return "", err
	}

	return project.TokenPath(), nil
}

// GetProjectDepositAmount returns the deposit amount of a project by its ID.
// Returns 0 and error if project not found.
//
// Parameters:
//   - projectId: unique launchpad project identifier to look up.
//
// Returns:
//   - amount: project-level token amount deposited for distribution; zero when absent.
//   - err: nil when found; non-nil when projectId is not present in state.
func (lp *launchpadV1) GetProjectDepositAmount(projectId string) (int64, error) {
	project, err := lp.getProject(projectId)
	if err != nil {
		return 0, err
	}

	return project.DepositAmount(), nil
}

// GetProjectRecipient returns the recipient address of a project by its ID.
// Returns empty address and error if project not found.
//
// Parameters:
//   - projectId: unique launchpad project identifier to look up.
//
// Returns:
//   - recipient: address configured to receive the project's tokens; empty address when absent.
//   - err: nil when found; non-nil when projectId is not present in state.
func (lp *launchpadV1) GetProjectRecipient(projectId string) (address, error) {
	project, err := lp.getProject(projectId)
	if err != nil {
		return address(""), err
	}

	return project.Recipient(), nil
}

// GetProjectCondition retrieves a specific condition of a project.
// Returns nil and error if project or condition not found.
//
// Parameters:
//   - projectId: unique launchpad project identifier to look up.
//   - tokenPath: condition-token contract path used as the project's condition key.
//
// Returns:
//   - condition: matching project condition; nil when the project or condition is absent.
//   - err: nil when found; non-nil when projectId or tokenPath is not present.
func (lp *launchpadV1) GetProjectCondition(projectId string, tokenPath string) (*launchpad.ProjectCondition, error) {
	project, err := lp.getProject(projectId)
	if err != nil {
		return nil, err
	}

	conditions := project.Conditions()
	condition, exists := conditions[tokenPath]
	if !exists {
		return nil, makeErrorWithDetails(errDataNotFound, ufmt.Sprintf("condition(%s) not found", tokenPath))
	}

	return condition, nil
}

// GetProjectTiersRatios returns the tiers ratios map of a project by its ID.
// Returns nil and error if project not found.
//
// Parameters:
//   - projectId: unique launchpad project identifier to look up.
//
// Returns:
//   - ratios: map from tier duration (30, 90, or 180) to its allocation percentage; nil when the project is absent.
//   - err: nil when found; non-nil when projectId is not present in state.
