package launchpad

import (
	"gno.land/r/gnoswap/launchpad"
)

// The functions below are makeEntrySafeFn transformations handed to
// rotree.Wrap. They run on every read through a read-only view, so each one
// returns a value the caller may hold without reaching realm-owned state.

// cloneProjectEntry is the transformation for the project tree. Project is
// mutable and its setters are declared in /r/gnoswap/launchpad, so an external
// holder of the stored pointer could write realm state through it.
//
// Project.Clone leaves the project's maps nil; see it for which lookups read
// them instead.
func cloneProjectEntry(value any) any {
	project, ok := value.(*launchpad.Project)
	if !ok {
		return nil
	}

	return project.Clone()
}

// cloneRewardStateEntry is the transformation for a project tier's reward
// tree. RewardState is mutable and its setters are declared in
// /r/gnoswap/launchpad, so an external holder of the stored pointer could
// write realm state through it.
func cloneRewardStateEntry(value any) any {
	rewardState, ok := value.(*launchpad.RewardState)
	if !ok {
		return nil
	}

	return rewardState.Clone()
}

package launchpad

import "gno.land/r/gnoswap/launchpad"

func init(cur realm) {
	registerLaunchpadV1(cur)
}

func registerLaunchpadV1(cur realm) {
	launchpad.RegisterInitializer(cross(cur), func(_ int, rlm realm, launchpadStore launchpad.ILaunchpadStore) launchpad.ILaunchpad {
		err := initStoreData(0, rlm, launchpadStore)
		if err != nil {
			panic(err)
		}

		return NewLaunchpadV1(launchpadStore)
	})
}

func initStoreData(_ int, rlm realm, launchpadStore launchpad.ILaunchpadStore) error {
	if !launchpadStore.HasProjectsKey() {
		err := launchpadStore.SetProjects(0, rlm, launchpad.NewBPTreeN(16))
		if err != nil {
			return err
		}
	}

	if !launchpadStore.HasProjectRecipientsKey() {
		err := launchpadStore.SetProjectRecipients(0, rlm, launchpad.NewBPTreeN(16))
		if err != nil {
			return err
		}
	}

	if !launchpadStore.HasProjectTierRewardManagersKey() {
		err := launchpadStore.SetProjectTierRewardManagers(0, rlm, launchpad.NewBPTreeN(16))
		if err != nil {
			return err
		}
	}

	if !launchpadStore.HasDepositCounterStoreKey() {
		err := launchpadStore.SetDepositCounter(0, rlm, launchpad.NewCounter())
		if err != nil {
			return err
		}
	}

	if !launchpadStore.HasDepositsKey() {
		err := launchpadStore.SetDeposits(0, rlm, launchpad.NewBPTreeN(16))
		if err != nil {
			return err
		}
	}

	if !launchpadStore.HasTotalGNSStakedAmountKey() {
		err := launchpadStore.SetTotalGNSStakedAmount(0, rlm, 0)
		if err != nil {
			return err
		}
	}

	return nil
}

