package protocol_fee

import (
	"chain"
	"errors"
	"strconv"

	ufmt "gno.land/p/nt/ufmt/v0"

	gnsmath "gno.land/p/gnoswap/gnsmath/v1"
	prabc "gno.land/p/gnoswap/rbac/v1"
	"gno.land/r/gnoswap/access/v1"
	"gno.land/r/gnoswap/common"
	"gno.land/r/gnoswap/halt/v1"
)

// DistributeProtocolFee distributes collected protocol fees.
//
// Splits fees between devOps and gov/staker based on configured percentages.
// This function processes all accumulated fees since last distribution.
//
// Only callable by admin or gov/staker contract.
// Note: Default split is 0% devOps, 100% gov/staker.
//
// Parameters:
//   - _: cross-call discriminator; callers pass 0
//   - rlm: propagated protocol_fee realm context; it must match the current crossing frame
func (pf *protocolFeeV1) DistributeProtocolFee(_ int, rlm realm) {
	access.AssertIsRlmCurrent(0, rlm)

	prev := rlm.Previous()
	assertIsAdminOrGovStaker(prev.Address())

	if halt.IsHaltedWithdraw() {
		return
	}

	protocolFeeAddr := access.MustGetAddress(prabc.ROLE_PROTOCOL_FEE.String())
	pfs := pf.getProtocolFeeState()

	reservedTokens := pfs.ReservedTokens()

	for _, token := range reservedTokens {
		pf.distributeProtocolFeeForToken(
			0,
			rlm,
			pfs,
			protocolFeeAddr,
			token,
		)
	}
}

// DistributeProtocolFeeByTokenPath distributes collected protocol fees for one token path.
//
// Parameters:
//   - _: cross-call discriminator; callers pass 0
//   - rlm: propagated protocol_fee realm context; it must match the current crossing frame
//   - tokenPath: token contract path whose reserved fee is eligible for distribution
func (pf *protocolFeeV1) DistributeProtocolFeeByTokenPath(_ int, rlm realm, tokenPath string) {
	access.AssertIsRlmCurrent(0, rlm)

	prev := rlm.Previous()
	assertIsAdminOrGovStaker(prev.Address())

	if halt.IsHaltedWithdraw() {
		return
	}

	protocolFeeAddr := access.MustGetAddress(prabc.ROLE_PROTOCOL_FEE.String())
	pfs := pf.getProtocolFeeState()

	if !pfs.store.HasReservedToken(tokenPath) {
		return
	}

	pf.distributeProtocolFeeForToken(
		0,
		rlm,
		pfs,
		protocolFeeAddr,
		tokenPath,
	)
}

// distributeProtocolFeeForToken validates and distributes one reserved token's pending fees.
func (pf *protocolFeeV1) distributeProtocolFeeForToken(_ int, rlm realm, pfs *protocolFeeState, protocolFeeAddr address, tokenPath string) {
	toDevOpsAmount := gnsmath.SafeSubInt64(
		pfs.GetAccuTransferToDevOpsByTokenPath(tokenPath),
		pfs.GetActualDistributedToDevOpsByTokenPath(tokenPath),
	)
	toGovStakerAmount := gnsmath.SafeSubInt64(
		pfs.GetAccuTransferToGovStakerByTokenPath(tokenPath),
		pfs.GetActualDistributedToGovStakerByTokenPath(tokenPath),
	)

	amount := gnsmath.SafeAddInt64(toDevOpsAmount, toGovStakerAmount)
	balance := common.BalanceOf(tokenPath, protocolFeeAddr)

	// amount should be less than or equal to balance
	if amount > balance {
		panic(makeErrorWithDetail(
			errInvalidAmount,
			ufmt.Sprintf("amount: %d should be less than or equal to balance: %d", amount, balance),
		))
	}

	if err := pfs.removeReservedToken(0, rlm, tokenPath); err != nil {
		panic(err)
	}

	if amount <= 0 {
		return
	}

	// distributeToDevOps and distributeToGovStaker record history before transferring.
	if err := pfs.distributeToDevOps(0, rlm, tokenPath, toDevOpsAmount); err != nil {
		panic(err)
	}
	if err := pfs.distributeToGovStaker(0, rlm, tokenPath, toGovStakerAmount); err != nil {
		panic(err)
	}

	prev := rlm.Previous()

	chain.Emit(
		"TransferProtocolFee",
		"prevAddr", prev.Address().String(),
		"prevRealm", prev.PkgPath(),
		"tokenPath", tokenPath,
		"toDevOpsAmount", strconv.FormatInt(toDevOpsAmount, 10),
		"toGovStakerAmount", strconv.FormatInt(toGovStakerAmount, 10),
		"amount", strconv.FormatInt(amount, 10),
	)
}

// SetDevOpsPct sets the devOpsPct.
//
// Parameters:
//   - _: cross-call discriminator; callers pass 0
//   - rlm: propagated protocol_fee realm context; it must match the current crossing frame
//   - pct: percentage for devOps (0-10000, where 10000 = 100%)
//
// Only callable by admin or governance.
// Note: GovStaker percentage is automatically adjusted to (10000 - devOpsPct).
func (pf *protocolFeeV1) SetDevOpsPct(_ int, rlm realm, pct int64) {
	access.AssertIsRlmCurrent(0, rlm)

	halt.AssertIsNotHaltedProtocolFee()

	prev := rlm.Previous()
	access.AssertIsAdminOrGovernance(prev.Address())

	assertIsValidPercent(pct)

	prevDevOpsPct := pf.getProtocolFeeState().DevOpsPct()
	prevGovStakerPct := pf.getProtocolFeeState().GovStakerPct()

	newDevOpsPct, err := pf.getProtocolFeeState().setDevOpsPct(0, rlm, pct)
	if err != nil {
		panic(err)
	}
	newGovStakerPct := pf.getProtocolFeeState().GovStakerPct()

	chain.Emit(
		"SetDevOpsPct",
		"prevAddr", prev.Address().String(),
		"prevRealm", prev.PkgPath(),
		"newDevOpsPct", strconv.FormatInt(newDevOpsPct, 10),
		"prevDevOpsPct", strconv.FormatInt(prevDevOpsPct, 10),
		"newGovStakerPct", strconv.FormatInt(newGovStakerPct, 10),
		"prevGovStakerPct", strconv.FormatInt(prevGovStakerPct, 10),
	)
}

// SetGovStakerPct sets the stakerPct.
//
// Parameters:
//   - _: cross-call discriminator; callers pass 0
//   - rlm: propagated protocol_fee realm context; it must match the current crossing frame
//   - pct: percentage for gov/staker (0-10000, where 10000 = 100%)
//
// Only callable by admin or governance.
// Note: DevOps percentage is automatically adjusted to (10000 - govStakerPct).
func (pf *protocolFeeV1) SetGovStakerPct(_ int, rlm realm, pct int64) {
	access.AssertIsRlmCurrent(0, rlm)

	halt.AssertIsNotHaltedProtocolFee()

	prev := rlm.Previous()
	access.AssertIsAdminOrGovernance(prev.Address())

	assertIsValidPercent(pct)

	prevDevOpsPct := pf.getProtocolFeeState().DevOpsPct()
	prevGovStakerPct := pf.getProtocolFeeState().GovStakerPct()

	newGovStakerPct, err := pf.getProtocolFeeState().setGovStakerPct(0, rlm, pct)
	if err != nil {
		panic(err)
	}
	newDevOpsPct := pf.getProtocolFeeState().DevOpsPct()

	chain.Emit(
		"SetGovStakerPct",
		"prevAddr", prev.Address().String(),
		"prevRealm", prev.PkgPath(),
		"newDevOpsPct", strconv.FormatInt(newDevOpsPct, 10),
		"prevDevOpsPct", strconv.FormatInt(prevDevOpsPct, 10),
		"newGovStakerPct", strconv.FormatInt(newGovStakerPct, 10),
		"prevGovStakerPct", strconv.FormatInt(prevGovStakerPct, 10),
	)
}

// AddToProtocolFee pulls the approved amount into protocol fee accounting.
//
// Parameters:
//   - _: cross-call discriminator; callers pass 0
//   - rlm: propagated protocol_fee realm context; a non-current value returns errSpoofedRealm
//   - tokenPath: token contract path from which the approved fee is pulled
//   - amount: non-negative fee amount in token base units; zero returns nil without transferring
//
// Returns:
//   - err: nil on success; errSpoofedRealm for a spoofed-realm call; errProtocolFeeHalted when protocol-fee collection is halted
//
// Only callable by pool, position, router, staker, or order (DCA/limit) contracts.
// Caller must approve the protocol fee realm for at least amount before calling.
// Note: Accumulated fees are distributed when DistributeProtocolFee is called.
func (pf *protocolFeeV1) AddToProtocolFee(_ int, rlm realm, tokenPath string, amount int64) error {
	if !rlm.IsCurrent() {
		return errors.New(errSpoofedRealm)
	}

	if halt.IsHaltedProtocolFee() {
		return errors.New(errProtocolFeeHalted)
	}

	prev := rlm.Previous()
	caller := prev.Address()
	assertIsAuthorizedFeeCaller(caller)

	if amount < 0 {
		panic(makeErrorWithDetail(
			errInvalidAmount,
			ufmt.Sprintf("amount(%d) should not be negative", amount),
		))
	}

	if amount == 0 {
		return nil
	}

	pf.reserveCollectedProtocolFee(0, rlm, tokenPath, amount)
	protocolFeeAddr := access.MustGetAddress(prabc.ROLE_PROTOCOL_FEE.String())
	common.SafeGRC20TransferFrom(0, rlm, tokenPath, caller, protocolFeeAddr, amount)

	chain.Emit(
		"AddToProtocolFee",
		"prevAddr", caller.String(),
		"prevRealm", prev.PkgPath(),
		"tokenPath", tokenPath,
		"amount", strconv.FormatInt(amount, 10),
	)

	return nil
}

func (pf *protocolFeeV1) reserveCollectedProtocolFee(_ int, rlm realm, tokenPath string, amount int64) {
	pfs := pf.getProtocolFeeState()

	toDevOpsAmount := gnsmath.SafeMulDivInt64(amount, pfs.DevOpsPct(), 10000)
	toGovStakerAmount := gnsmath.SafeSubInt64(amount, toDevOpsAmount)

	if err := pfs.addAccuToDevOps(0, rlm, tokenPath, toDevOpsAmount); err != nil {
		panic(err)
	}
	if err := pfs.addAccuToGovStaker(0, rlm, tokenPath, toGovStakerAmount); err != nil {
		panic(err)
	}

	if err := pfs.store.AddReservedToken(0, rlm, tokenPath); err != nil {
		panic(err)
	}

	// Bucket the gov/staker share under the accrual epoch in force so that gov/staker
	// can later fold it against the stake distribution that was live when it arrived.
	// A split that leaves gov/staker nothing moves no accumulator, so it is not bucketed.
	if toGovStakerAmount > 0 {
		epoch := pfs.store.GetAccrualEpoch()
		if err := pfs.store.AddAccrualBucket(0, rlm, tokenPath, epoch, toGovStakerAmount); err != nil {
			panic(err)
		}
		if err := pfs.store.AddAccrualPendingToken(0, rlm, tokenPath); err != nil {
			panic(err)
		}
	}
}

// AdvanceAccrualEpoch closes the accrual epoch in force and returns the new one.
//
// gov/staker calls it on every stake change, before it records the new stake
// distribution, so every fee bucketed from now on is attributed to that distribution.
// Restricted to gov/staker: an epoch advanced by anyone else would fragment the buckets
// without a matching stake record on the gov/staker side.
//
// Parameters:
//   - _: cross-call discriminator; callers pass 0
//   - rlm: propagated protocol_fee realm context; it must be current and be called by GovStaker
//
// Returns:
//   - epoch: newly stored non-negative accrual epoch for fees collected after the stake change
func (pf *protocolFeeV1) AdvanceAccrualEpoch(_ int, rlm realm) int64 {
	if !rlm.IsCurrent() {
		panic(errors.New(errSpoofedRealm))
	}

	prev := rlm.Previous()
	access.AssertIsGovStaker(prev.Address())

	pfs := pf.getProtocolFeeState()
	epoch := gnsmath.SafeAddInt64(pfs.store.GetAccrualEpoch(), 1)
	if err := pfs.store.SetAccrualEpoch(0, rlm, epoch); err != nil {
		panic(err)
	}

	return epoch
}

// ConsumeAccrualBuckets returns and clears up to limit of the oldest pending buckets of
// tokenPath, as parallel epoch and amount slices in epoch order. A limit of zero or
// less consumes every pending bucket. Once no bucket remains the token leaves the
// pending set.
//
// Restricted to gov/staker: clearing a bucket without folding it into an accumulator
// would strand that fee share.
//
// Parameters:
//   - _: cross-call discriminator; callers pass 0
//   - rlm: propagated protocol_fee realm context; it must be current and be called by GovStaker
//   - tokenPath: token contract path whose pending accrual buckets are consumed
//   - limit: maximum number of oldest buckets to consume; zero or negative consumes all pending buckets
//
// Returns:
//   - epochs: consumed accrual epoch numbers in ascending epoch order
//   - amounts: fee amounts corresponding positionally to epochs, in token base units
func (pf *protocolFeeV1) ConsumeAccrualBuckets(_ int, rlm realm, tokenPath string, limit int) ([]int64, []int64) {
	if !rlm.IsCurrent() {
		panic(errors.New(errSpoofedRealm))
	}

	prev := rlm.Previous()
	access.AssertIsGovStaker(prev.Address())

	pfs := pf.getProtocolFeeState()
	epochs, amounts := pfs.store.GetAccrualBuckets(tokenPath, limit)
	if len(epochs) == 0 {
		return epochs, amounts
	}

	if err := pfs.store.RemoveAccrualBuckets(0, rlm, tokenPath, epochs); err != nil {
		panic(err)
	}

	remainingEpochs, _ := pfs.store.GetAccrualBuckets(tokenPath, 1)
	if len(remainingEpochs) == 0 {
		if err := pfs.store.RemoveAccrualPendingToken(0, rlm, tokenPath); err != nil {
			panic(err)
		}
	}

	return epochs, amounts
}

package protocol_fee

import (
	bptree "gno.land/p/nt/bptree/v0"
	ufmt "gno.land/p/nt/ufmt/v0"

	gnsmath "gno.land/p/gnoswap/gnsmath/v1"
	prabc "gno.land/p/gnoswap/rbac/v1"
	"gno.land/r/gnoswap/access/v1"
	"gno.land/r/gnoswap/common"
	"gno.land/r/gnoswap/protocol_fee"
)

// protocolFeeState holds all the state variables for protocol fee management
type protocolFeeState struct {
	store protocol_fee.IProtocolFeeStore
}

// DevOpsPct returns the percentage of protocol fees allocated to DevOps.
//
// Returns:
//   - pct: Stored DevOps protocol-fee allocation percentage in basis points.
func (pfs *protocolFeeState) DevOpsPct() int64 {
	return pfs.store.GetDevOpsPct()
}

// GovStakerPct returns the percentage of protocol fees allocated to Gov/Staker.
//
// Returns:
//   - pct: Gov/Staker protocol-fee allocation percentage in basis points, computed as 10000 minus the stored DevOps percentage.
func (pfs *protocolFeeState) GovStakerPct() int64 {
	return 10000 - pfs.store.GetDevOpsPct()
}

// AccuToGovStaker returns the cumulative amount allocated to GovStaker.
// It includes allocations that may still be pending distribution; completed
// transfers are tracked separately in the distribution history.
//
// Returns:
//   - tree: BP-tree mapping token paths to cumulative amounts allocated to Gov/Staker, including allocations pending distribution.
func (pfs *protocolFeeState) AccuToGovStaker() *bptree.BPTree {
	return pfs.store.GetAccuToGovStaker()
}

// AccuToDevOps returns the cumulative amount allocated to DevOps.
// It includes allocations that may still be pending distribution; completed
// transfers are tracked separately in the distribution history.
//
// Returns:
//   - tree: BP-tree mapping token paths to cumulative amounts allocated to DevOps, including allocations pending distribution.
func (pfs *protocolFeeState) AccuToDevOps() *bptree.BPTree {
	return pfs.store.GetAccuToDevOps()
}

// ActualDistributedToGovStaker returns the cumulative amounts actually distributed to Gov/Staker.
//
// Returns:
//   - tree: BP-tree mapping token paths to cumulative amounts actually distributed to Gov/Staker.
func (pfs *protocolFeeState) ActualDistributedToGovStaker() *bptree.BPTree {
	return pfs.store.GetDistributedToGovStakerHistory()
}

// ActualDistributedToDevOps returns the cumulative amounts actually distributed to DevOps.
//
// Returns:
//   - tree: BP-tree mapping token paths to cumulative amounts actually distributed to DevOps.
func (pfs *protocolFeeState) ActualDistributedToDevOps() *bptree.BPTree {
	return pfs.store.GetDistributedToDevOpsHistory()
}

// ReservedTokens returns token paths reserved for distribution.
//
// Returns:
//   - tokenPaths: Token paths currently reserved for protocol-fee distribution.
func (pfs *protocolFeeState) ReservedTokens() []string {
	return pfs.store.GetReservedTokens()
}

// distributeToDevOps distributes tokens to DevOps and updates related state.
// Amount should be greater than 0 (already checked in DistributeProtocolFee).
func (pfs *protocolFeeState) distributeToDevOps(_ int, rlm realm, token string, amount int64) error {
	devOpsAddr := access.MustGetAddress(prabc.ROLE_DEVOPS.String())

	if err := pfs.addActualDistributedToDevOps(0, rlm, token, amount); err != nil {
		return err
	}
	common.SafeGRC20Transfer(0, rlm, token, devOpsAddr, amount)

	return nil
}

// distributeToGovStaker distributes tokens to Gov/Staker and updates related state.
// Amount should be greater than 0 (already checked in DistributeProtocolFee).
func (pfs *protocolFeeState) distributeToGovStaker(_ int, rlm realm, token string, amount int64) error {
	govStakerAddr := access.MustGetAddress(prabc.ROLE_GOV_STAKER.String())

	if err := pfs.addActualDistributedToGovStaker(0, rlm, token, amount); err != nil {
		return err
	}
	common.SafeGRC20Transfer(0, rlm, token, govStakerAddr, amount)

	return nil
}

// setDevOpsPct sets the devOpsPct.
func (pfs *protocolFeeState) setDevOpsPct(_ int, rlm realm, pct int64) (int64, error) {
	if pct < 0 {
		return 0, makeErrorWithDetail(
			errInvalidPct,
			ufmt.Sprintf("pct(%d) should not be negative", pct),
		)
	}
	if pct > 10000 {
		return 0, makeErrorWithDetail(
			errInvalidPct,
			ufmt.Sprintf("pct(%d) should not be bigger than 10000", pct),
		)
	}

	if err := pfs.store.SetDevOpsPct(0, rlm, pct); err != nil {
		return 0, err
	}

	return pct, nil
}

// setGovStakerPct sets the govStakerPct by calculating devOpsPct.
func (pfs *protocolFeeState) setGovStakerPct(_ int, rlm realm, pct int64) (int64, error) {
	if pct < 0 {
		return 0, makeErrorWithDetail(
			errInvalidPct,
			ufmt.Sprintf("pct(%d) should not be negative", pct),
		)
	}

	devOpsPct := 10000 - pct

	if _, err := pfs.setDevOpsPct(0, rlm, devOpsPct); err != nil {
		return 0, err
	}

	return pct, nil
}

// addAccuToGovStaker adds the amount to the accuToGovStaker by token path.
func (pfs *protocolFeeState) addAccuToGovStaker(_ int, rlm realm, tokenPath string, amount int64) error {
	before := pfs.GetAccuTransferToGovStakerByTokenPath(tokenPath)

	// Check for overflow
	after := gnsmath.SafeAddInt64(before, amount)
	if err := pfs.store.SetAccuToGovStakerItem(0, rlm, tokenPath, after); err != nil {
		return err
	}
	return nil
}

// addAccuToDevOps adds the amount to the accuToDevOps by token path.
func (pfs *protocolFeeState) addAccuToDevOps(_ int, rlm realm, tokenPath string, amount int64) error {
	before := pfs.GetAccuTransferToDevOpsByTokenPath(tokenPath)

	// Check for overflow
	after := gnsmath.SafeAddInt64(before, amount)
	if err := pfs.store.SetAccuToDevOpsItem(0, rlm, tokenPath, after); err != nil {
		return err
	}
	return nil
}

// addActualDistributedToGovStaker adds the amount to the actual distributed amount to gov/staker by token path.
func (pfs *protocolFeeState) addActualDistributedToGovStaker(_ int, rlm realm, tokenPath string, amount int64) error {
	before := pfs.GetActualDistributedToGovStakerByTokenPath(tokenPath)
	after := gnsmath.SafeAddInt64(before, amount)
	if err := pfs.store.SetDistributedToGovStakerHistoryItem(0, rlm, tokenPath, after); err != nil {
		return err
	}
	return nil
}

// addActualDistributedToDevOps adds the amount to the actual distributed amount to devOps by token path.
func (pfs *protocolFeeState) addActualDistributedToDevOps(_ int, rlm realm, tokenPath string, amount int64) error {
	before := pfs.GetActualDistributedToDevOpsByTokenPath(tokenPath)
	after := gnsmath.SafeAddInt64(before, amount)
	if err := pfs.store.SetDistributedToDevOpsHistoryItem(0, rlm, tokenPath, after); err != nil {
		return err
	}
	return nil
}

// GetAccuTransferToGovStakerByTokenPath gets the accumulated amount to gov/staker by token path.
//
// Parameters:
//   - tokenPath: Token path whose cumulative Gov/Staker allocation should be read.
//
// Returns:
//   - amount: Cumulative Gov/Staker allocation for tokenPath, or zero when no entry is recorded.
func (pfs *protocolFeeState) GetAccuTransferToGovStakerByTokenPath(tokenPath string) int64 {
	return retrieveAmount(pfs.store.GetAccuToGovStaker(), tokenPath)
}

// GetAccuTransferToDevOpsByTokenPath gets the accumulated amount to devOps by token path.
//
// Parameters:
//   - tokenPath: Token path whose cumulative DevOps allocation should be read.
//
// Returns:
//   - amount: Cumulative DevOps allocation for tokenPath, or zero when no entry is recorded.
func (pfs *protocolFeeState) GetAccuTransferToDevOpsByTokenPath(tokenPath string) int64 {
	return retrieveAmount(pfs.store.GetAccuToDevOps(), tokenPath)
}

// GetActualDistributedToGovStakerByTokenPath gets the actual distributed amount to gov/staker by token path.
//
// Parameters:
//   - tokenPath: Token path whose cumulative actual Gov/Staker distribution should be read.
//
// Returns:
//   - amount: Cumulative amount actually distributed to Gov/Staker for tokenPath, or zero when no history is recorded.
func (pfs *protocolFeeState) GetActualDistributedToGovStakerByTokenPath(tokenPath string) int64 {
	return retrieveAmount(pfs.store.GetDistributedToGovStakerHistory(), tokenPath)
}

// GetActualDistributedToDevOpsByTokenPath gets the actual distributed amount to devOps by token path.
//
// Parameters:
//   - tokenPath: Token path whose cumulative actual DevOps distribution should be read.
//
// Returns:
//   - amount: Cumulative amount actually distributed to DevOps for tokenPath, or zero when no history is recorded.
func (pfs *protocolFeeState) GetActualDistributedToDevOpsByTokenPath(tokenPath string) int64 {
	return retrieveAmount(pfs.store.GetDistributedToDevOpsHistory(), tokenPath)
}

// removeReservedToken removes one distributed token from the reserved token index.
func (pfs *protocolFeeState) removeReservedToken(_ int, rlm realm, tokenPath string) error {
	return pfs.store.RemoveReservedToken(0, rlm, tokenPath)
}

// NewProtocolFeeState creates a new instance of protocolFeeState with initialized values
//
// Parameters:
//   - protocolFeeStore: Store implementation backing the new protocol-fee state view.
//
// Returns:
//   - state: New protocolFeeState wrapper backed by protocolFeeStore.
func NewProtocolFeeStateBy(protocolFeeStore protocol_fee.IProtocolFeeStore) *protocolFeeState {
	return &protocolFeeState{
		store: protocolFeeStore,
	}
}

func retrieveAmount(tree *bptree.BPTree, key string) int64 {
	amountI := tree.Get(key)
	if amountI == nil {
		return 0
	}
	res, ok := amountI.(int64)
	if !ok {
		panic(ufmt.Sprintf("failed to cast amount to int64: %T", amountI))
	}
	return res
}

package manager

type Access struct {
	Since TimePoint
}

func NewAccess(since TimePoint) Access {
	return Access{
		Since: since,
	}
}

func NewAccessWithDelay(since TimePoint, delay uint32) Access {
	if since.IsZero() {
		return Access{Since: 0}
	}

	return Access{
		Since: since + TimePoint(delay),
	}
}

func (access Access) isActiveAt(now TimePoint) bool {
	if access.Since.IsZero() {
		return false
	}

	return !access.Since.After(now)
}

package manager

const (
	AdminRole  RoleId = 0
	PublicRole RoleId = 1<<64 - 1 // uint64 max

	// MinSetback is the minimum setback for a grant delay change (5 days).
	// OpenZeppelin: https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L164-L166
	MinSetback uint32 = 5 * 24 * 60 * 60
)

package manager

// Delay is a value that changes only after a setback, mirroring
// OpenZeppelin's packed `Delay` type.
// OpenZeppelin: https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/utils/types/Time.sol#L61
type Delay struct {
	effectDate  TimePoint
	valueBefore uint32
	valueAfter  uint32
}

func NewDelay(delay uint32) Delay {
	return Delay{effectDate: 0, valueBefore: 0, valueAfter: delay}
}

// Get returns the value active at timestamp.
// OpenZeppelin: https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/utils/types/Time.sol#L86-L96
func (d Delay) Get(timestamp TimePoint) uint32 {
	if d.effectDate.After(timestamp) {
		return d.valueBefore
	}

	return d.valueAfter
}

// WithUpdate schedules newDelay to take effect at timestamp plus a setback:
// at least minSetback, or longer when newDelay decreases the active value
// by more than minSetback. Returns the updated Delay and the effect timePoint.
// OpenZeppelin: https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/utils/types/Time.sol#L103-L112
func (d Delay) WithUpdate(timestamp TimePoint, newDelay uint32, minSetback uint32) (Delay, TimePoint) {
	value := d.Get(timestamp)

	setback := minSetback
	if value > newDelay {
		if diff := value - newDelay; diff > setback {
			setback = diff
		}
	}

	effect := NewTimePoint(timestamp.Int64() + int64(setback))

	return Delay{effectDate: effect, valueBefore: value, valueAfter: newDelay}, effect
}

// Package manager is a pure port of the core permission model of
// OpenZeppelin Contracts AccessManager v5.6.1, taken from
// gno.land/p/onbloc/access/manager (github.com/onbloc/gno-ibc, Apache-2.0).
//
// It is a state transition library, not a realm: it does not own storage,
// inspect realms, or decide who the caller is. A realm stores a State,
// passes the caller address, target, and selector into its methods, and
// exposes the management API it needs (see gno.land/r/gnoswap/order/keeper).
//
// Model:
//   - roles are uint64 identifiers; AdminRole is 0 and PublicRole is
//     uint64 max, which every account holds;
//   - permissions are scoped by target and selector; an unset selector
//     defaults to AdminRole;
//   - a closed target rejects every call;
//   - each role has an admin role, a grant delay, and member records with
//     an activation time.
//
// Delayed operation scheduling (schedule, execute, cancel) is not ported.
// Panics carry string messages so they can cross realm boundaries.
package manager

package manager

import (
	"errors"
	"strings"
)

var (
	errAccessManagerLockedRole      = errors.New("access manager locked role")
	errAccessManagerBadConfirmation = errors.New("access manager bad confirmation")
	errAccessManagerLastAdmin       = errors.New("access manager last admin")
)

func errorWithDetails(err error, msgs ...string) error {
	if len(msgs) == 0 {
		return err
	}

	return errors.New(err.Error() + ", " + strings.Join(msgs, ", "))
}

package manager

import "gno.land/p/nt/ufmt/v0"

// RequireUnlockedConfigRole rejects role ids whose configuration is locked.
// Use this before emitting RoleLabel metadata from a realm.
// OpenZeppelin reference:
// https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L226-L230
func RequireUnlockedConfigRole(role RoleId) {
	if role == AdminRole || role == PublicRole {
		panic(errorWithDetails(errAccessManagerLockedRole, ufmt.Sprintf("role %d is locked", role)).Error())
	}
}

package manager

import "gno.land/p/nt/ufmt/v0"

type State struct {
	Roles   map[RoleId]*RoleConfig
	Targets map[string]*TargetConfig
}

func NewState() State {
	return State{
		Roles:   make(map[RoleId]*RoleConfig),
		Targets: make(map[string]*TargetConfig),
	}
}

// =================================================== GETTERS ====================================================

// CanCall reports whether caller can call target selector immediately.
// This Gno port returns only immediate authorization because scheduled
// execution and execution delay are intentionally not ported.
// OpenZeppelin reference:
// https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L140-L156
func (state *State) CanCall(caller address, target string, selector Selector) CanCallResult {
	if state.IsTargetClosed(target) {
		return NewCanCallResult(false)
	}

	role := state.GetTargetFunctionRole(target, selector)

	membership := state.HasRole(role, caller)
	if !membership.IsMember {
		return NewCanCallResult(false)
	}

	return NewCanCallResult(true)
}

// IsAuthorized is a boolean convenience wrapper around CanCall.
// OpenZeppelin reference:
// https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L140-L156
func (state *State) IsAuthorized(caller address, target string, selector Selector) bool {
	return state.CanCall(caller, target, selector).Immediate
}

// HasRole reports whether account currently has an active role membership.
// This Gno port returns membership only because execution delay is not ported.
// OpenZeppelin reference:
// https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L211-L220
func (state *State) HasRole(role RoleId, account address) HasRoleResult {
	if role == PublicRole {
		return NewHasRoleResult(true)
	}

	roleConfig := state.getRole(role)
	if roleConfig == nil {
		return NewHasRoleResult(false)
	}

	return NewHasRoleResult(roleConfig.hasMember(account, CurrentTimePoint()))
}

// GetRoleMemberSince returns when account's role membership became active,
// or zero if it is not a member. It corresponds to OpenZeppelin's since field;
// execution-delay fields are not ported here.
//
// OpenZeppelin: https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L205
func (state *State) GetRoleMemberSince(role RoleId, account address) TimePoint {
	roleConfig := state.getRole(role)
	if roleConfig == nil {
		return 0
	}

	access, found := roleConfig.Members[account]
	if !found {
		return 0
	}

	return access.Since
}

// GetRoleAdmin returns the admin role for role, defaulting to AdminRole.
// OpenZeppelin reference:
// https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L183-L186
func (state *State) GetRoleAdmin(role RoleId) RoleId {
	roleConfig := state.getRole(role)
	if roleConfig == nil {
		return AdminRole
	}

	return roleConfig.adminRole()
}

// GetRoleGrantDelay returns the grant delay currently in effect for role. A
// change scheduled by SetGrantDelay is not reflected until its effect timePoint.
// OpenZeppelin: https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L194-L196
func (state *State) GetRoleGrantDelay(role RoleId) uint32 {
	roleConfig := state.getRole(role)
	if roleConfig == nil {
		return 0
	}

	return roleConfig.grantDelay(CurrentTimePoint())
}

// GetRoleGrantDelayEffect returns when role's scheduled grant delay change
// takes effect. No OpenZeppelin equivalent; added to avoid direct field access.
func (state *State) GetRoleGrantDelayEffect(role RoleId) TimePoint {
	roleConfig := state.getRole(role)
	if roleConfig == nil {
		return 0
	}

	return roleConfig.GrantDelay.effectDate
}

// GetTargetFunctionRole returns the role required for target selector.
// Unconfigured selectors default to AdminRole in this Gno representation.
// OpenZeppelin reference:
// https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L173-L176
func (state *State) GetTargetFunctionRole(target string, selector Selector) RoleId {
	targetConfig := state.getTarget(target)
	if targetConfig == nil {
		return AdminRole
	}

	return targetConfig.functionRole(selector)
}

// IsTargetClosed reports whether target is closed.
// OpenZeppelin reference:
// https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L168-L171
func (state *State) IsTargetClosed(target string) bool {
	targetConfig := state.getTarget(target)

	return targetConfig != nil && targetConfig.isClosed()
}

// =============================================== ROLE MANAGEMENT ===============================================

// GrantRole grants role membership to account and returns true for a new member.
// This Gno port retains grant delay but intentionally omits OZ execution delay.
// OpenZeppelin references:
// https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L233-L236
// https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L271-L298
func (state *State) GrantRole(role RoleId, account address) bool {
	if role == PublicRole {
		panic(errorWithDetails(errAccessManagerLockedRole, ufmt.Sprintf("role %d is locked", role)).Error())
	}

	state.ensureRole(role)

	return state.getRole(role).grant(account, CurrentTimePoint())
}

// RevokeRole revokes role membership from account and reports whether it existed.
// OpenZeppelin references:
// https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L238-L240
// https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L300-L319
func (state *State) RevokeRole(role RoleId, account address) bool {
	if role == PublicRole {
		panic(errorWithDetails(errAccessManagerLockedRole, ufmt.Sprintf("role %d is locked", role)).Error())
	}

	state.ensureRole(role)

	if role == AdminRole && state.isLastAdmin(account) {
		panic(errAccessManagerLastAdmin.Error())
	}

	return state.getRole(role).revoke(account)
}

// isLastAdmin reports whether account is the only currently active AdminRole
// member. Prevents bricking the system by removing the final admin.
func (state *State) isLastAdmin(account address) bool {
	adminRole := state.getRole(AdminRole)
	if adminRole == nil {
		return false
	}

	now := CurrentTimePoint()
	if !adminRole.hasMember(account, now) {
		return false
	}

	for member, access := range adminRole.Members {
		if member != account && access.isActiveAt(now) {
			return false
		}
	}

	return true
}

// RenounceRole revokes caller-confirmed role membership from account.
// OpenZeppelin reference:
// https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L243-L249
func (state *State) RenounceRole(role RoleId, account address, callerConfirmation address) bool {
	if account != callerConfirmation {
		panic(errAccessManagerBadConfirmation.Error())
	}

	return state.RevokeRole(role, account)
}

// SetRoleAdmin sets the admin role that can grant or revoke role.
// OpenZeppelin references:
// https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L251-L254
// https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L321-L337
func (state *State) SetRoleAdmin(role RoleId, admin RoleId) {
	RequireUnlockedConfigRole(role)

	state.ensureRole(role)
	state.getRole(role).setAdmin(admin)
}

// SetGrantDelay schedules newDelay behind a setback; it never overwrites the
// active delay on the spot. Callers read GetRoleGrantDelay for the current
// value or GetRoleGrantDelayEffect for the effect timePoint.
// AdminRole is not locked here (unlike SetRoleAdmin) — OpenZeppelin only rejects PublicRole.
// OpenZeppelin: https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L262-L264,L362-L371
func (state *State) SetGrantDelay(role RoleId, newDelay uint32) {
	if role == PublicRole {
		panic(errorWithDetails(errAccessManagerLockedRole, ufmt.Sprintf("role %d is locked", role)).Error())
	}

	state.ensureRole(role)
	state.getRole(role).setGrantDelay(CurrentTimePoint(), newDelay)
}

// ============================================= FUNCTION MANAGEMENT ==============================================

// SetTargetFunctionRole sets the role required for target selector.
// OpenZeppelin reference:
// https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L385-L393
func (state *State) SetTargetFunctionRole(target string, selector Selector, role RoleId) {
	state.ensureTarget(target)
	state.getTarget(target).setFunctionRole(selector, role)
}

// SetTargetFunctionRoles sets the same role for multiple target selectors.
// OpenZeppelin reference:
// https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L373-L383
func (state *State) SetTargetFunctionRoles(target string, selectors []Selector, role RoleId) {
	state.ensureTarget(target)
	state.getTarget(target).setFunctionRoles(selectors, role)
}

// =============================================== MODE MANAGEMENT ================================================

// SetTargetClosed sets whether target rejects calls regardless of selector role.
// OpenZeppelin references:
// https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L412-L416
// https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L418-L426
func (state *State) SetTargetClosed(target string, closed bool) {
	state.ensureTarget(target)
	state.getTarget(target).setClosed(closed)
}

// ================================================= ADMIN LOGIC ==================================================

// CanAdminRole reports whether caller has the admin role required for role.
// OpenZeppelin reference:
// https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L652-L657
func (state *State) CanAdminRole(role RoleId, caller address) CanCallResult {
	adminRole := state.GetRoleAdmin(role)

	membership := state.HasRole(adminRole, caller)
	if !membership.IsMember {
		return NewCanCallResult(false)
	}

	return NewCanCallResult(true)
}

// CanManageTarget reports whether caller can manage target configuration.
// OpenZeppelin references:
// https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L101-L105
// https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L640-L650
func (state *State) CanManageTarget(caller address) CanCallResult {
	membership := state.HasRole(AdminRole, caller)
	if !membership.IsMember {
		return NewCanCallResult(false)
	}

	return NewCanCallResult(true)
}

func (state *State) getRole(role RoleId) *RoleConfig {
	return state.Roles[role]
}

func (state *State) getTarget(target string) *TargetConfig {
	return state.Targets[target]
}

func (state *State) ensureRole(role RoleId) {
	roleConfig, found := state.Roles[role]
	if !found || roleConfig == nil {
		state.Roles[role] = NewRoleConfig(AdminRole, 0)
	}
}

func (state *State) ensureTarget(target string) {
	targetConfig, found := state.Targets[target]
	if !found || targetConfig == nil {
		state.Targets[target] = NewTargetConfig(false)
	}
}

package manager

import "strconv"

type RoleId uint64

func NewRoleId(id uint64) RoleId {
	return RoleId(id)
}

func (r RoleId) Uint64() uint64 {
	return uint64(r)
}

func (r RoleId) String() string {
	return strconv.FormatUint(uint64(r), 10)
}

type RoleConfig struct {
	Members    map[address]Access
	Admin      RoleId
	GrantDelay Delay
}

func NewRoleConfig(admin RoleId, grantDelay uint32) *RoleConfig {
	return &RoleConfig{
		Members:    make(map[address]Access),
		Admin:      admin,
		GrantDelay: NewDelay(grantDelay),
	}
}

func (roleConfig *RoleConfig) grant(account address, now TimePoint) bool {
	_, found := roleConfig.Members[account]
	if found {
		return false
	}

	roleConfig.Members[account] = NewAccessWithDelay(now, roleConfig.grantDelay(now))

	return true
}

func (roleConfig *RoleConfig) revoke(account address) bool {
	_, found := roleConfig.Members[account]
	if found {
		delete(roleConfig.Members, account)
	}

	return found
}

func (roleConfig *RoleConfig) hasMember(account address, now TimePoint) bool {
	access, found := roleConfig.Members[account]
	if !found {
		return false
	}

	return access.isActiveAt(now)
}

func (roleConfig *RoleConfig) setAdmin(admin RoleId) {
	roleConfig.Admin = admin
}

func (roleConfig *RoleConfig) adminRole() RoleId {
	return roleConfig.Admin
}

// setGrantDelay schedules newDelay behind the MinSetback setback. Callers
// read the effect timePoint via State.GetRoleGrantDelayEffect.
// OpenZeppelin: https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L362-L371
func (roleConfig *RoleConfig) setGrantDelay(now TimePoint, newDelay uint32) {
	updated, _ := roleConfig.GrantDelay.WithUpdate(now, newDelay, MinSetback)
	roleConfig.GrantDelay = updated
}

// grantDelay returns the grant delay active at now.
// OpenZeppelin: https://github.com/OpenZeppelin/openzeppelin-contracts/blob/5fd1781b1454fd1ef8e722282f86f9293cacf256/contracts/access/manager/AccessManager.sol#L194-L196
func (roleConfig *RoleConfig) grantDelay(now TimePoint) uint32 {
	return roleConfig.GrantDelay.Get(now)
}

