// RegisterInitializer registers an implementation version.
// Each version calls it from init with a factory that receives the shared store.
// Only packages under this realm's path may register,
// and the first registration becomes active.
// A nil initializer is rejected here,
// instead of panicking later when the version is activated.
func RegisterInitializer(cur realm, initializer func(_ int, rlm realm, dcaStore pdca.IDCAOrderStore) pdca.IDCAOrder) {
	if initializer == nil {
		panic(ErrNilInitializer)
	}

	initializerFunc := func(_ int, rlm realm, domainStore any) any {
		access.AssertIsRlmCurrent(0, rlm)

		currentStore, ok := domainStore.(pdca.IDCAOrderStore)
		if !ok {
			panic(errInvalidDomainStore)
		}

		return initializer(0, rlm, currentStore)
	}

	err := versionManager.RegisterInitializer(0, cur, initializerFunc)
	if err != nil {
		panic(err.Error())
	}

	err = updateImplementation()
	if err != nil {
		panic(err.Error())
	}
}

// UpgradeImpl activates a previously registered version by package path.
// Admin or governance only.
func UpgradeImpl(cur realm, packagePath string) {
	caller := cur.Previous().Address()
	access.AssertIsAdminOrGovernance(caller)

	// The running version still writes the accumulator after its swap,
	// so never switch during a round.
	if NewDCAOrderStore(kvStore).IsExecuting() {
		panic(ErrUpgradeWhileExecuting)
	}

	err := versionManager.ChangeImplementation(0, cur, packagePath)
	if err != nil {
		panic(err.Error())
	}

	err = updateImplementation()
	if err != nil {
		panic(err.Error())
	}
}

// GetImplementationPackagePath returns the active implementation path.
func GetImplementationPackagePath() string {
	return versionManager.GetCurrentPackagePath()
}

// Package limit is the GnoSwap limit order realm.
//
// Users escrow makingAmount of tokenIn for takingAmount of tokenOut before
// expiresAt. Authorized keepers fill orders on a whitelisted direct pool,
// without the router, choosing the pool fee tier and swap price limit for
// each fill. Partial fills leave unsold input in escrow; each fill pays the
// owner immediately after deducting the order's snapshotted execution fee,
// while enforcing the order's slippage-adjusted owner-net exchange ratio.
// Owners can cancel for the remaining input, and anyone can refund expired
// orders through bounded cleanup. Settled orders are removed from the indexes.
//
// This package is the permanent entry point. It owns the escrow address, the
// KV store shared by every version, and the upgrade switch; the business
// logic lives in a registered implementation (impl/v0).
//
// Files:
//   - proxy.gno: state-changing entry points
//   - getter.gno: read-only queries
//   - store.gno: KV store and store keys
//   - state.gno: realm state and the active implementation
//   - upgrade.gno: implementation registration and upgrades
//   - swap_callback.gno: authenticated pool callback paying escrowed input
package limit

package limit

// Proxy errors carry no error code; codes belong to the implementation.

// ErrSpoofedRealm is returned when a store write gets a non-current realm.
const ErrSpoofedRealm = "spoofed realm"

// ErrNilInitializer is raised by RegisterInitializer for a nil factory.
const ErrNilInitializer = "nil initializer"

const (
	errImplNotInitialized                = "implementation is not initialized"
	errInvalidImpl                       = "impl is not an ILimitOrder"
	errInvalidDomainStore                = "domainStore is not an ILimitOrderStore"
	errNilConfig                         = "config is nil"
	errImplDoesNotSupportTargetedCleanup = "implementation does not support targeted expired-order cleanup"
	errImplDoesNotSupportFeeCollection   = "implementation does not support pending execution fee collection"

	// errInvalidSwapCallback is returned by an order's swap callback for a
	// call it must not pay.
	errInvalidSwapCallback = "invalid swap callback"

	// Format strings: the store key name, the config value.
	errNilValue          = "%s is nil"
	errInvalidConfigType = "failed to cast config: %T"
)

