type expiredOrderCleanup interface {
	CleanupExpiredOrdersByIDs(_ int, rlm realm, orderIDs string) (expired int, retryOrderIDs string)
}

type pendingExecutionFeeCollector interface {
	CollectPendingExecutionFee(_ int, rlm realm, tokenPath string) (int64, int64)
}

// CreateOrder escrows makingAmount of tokenIn for takingAmount of tokenOut.
// Each fill supplies its pool fee tier and price limit.
// slippageBps=0 enforces the making/taking ratio or better.
// expiresAt must be positive and within the configured duration bounds.
// The execution fee rate is snapshotted into each new order.
// baseToken must be tokenIn (Sell) or tokenOut (Buy); it is emitted only as
// creation metadata and does not affect the order's execution terms.
// The caller must first approve Address() for makingAmount.
// Reverts while execution is halted for Limit orders.
func CreateOrder(
	cur realm,
	tokenIn string,
	tokenOut string,
	makingAmount int64,
	takingAmount int64,
	slippageBps int64,
	expiresAt int64,
	baseToken string,
) uint64 {
	return getImplementation().CreateOrder(0, cur, tokenIn, tokenOut, makingAmount, takingAmount, slippageBps, expiresAt, baseToken)
}

// CancelOrder refunds the remaining input and removes the order from the indexes.
// A past-deadline refund uses the expired event.
// It returns the refunded input.
//
// Owner only. Reverts while withdrawals are halted for limit orders.
func CancelOrder(cur realm, orderID uint64) int64 {
	return getImplementation().CancelOrder(0, cur, orderID)
}

// ExecuteOrder fills up to maxAmountIn through the order's token pair at poolFee.
// A nonzero sqrtPriceLimitX96 stops at that pool price and may leave input
// unspent in escrow. Zero requires maxAmountIn to be consumed in full.
// The order's minimum owner-net output is enforced on the actual input.
// Returns actual input and pool output before the order's execution fee;
// the owner is paid immediately after that fee is deducted.
// The immediate caller must be authorized for ExecuteOrder by the shared
// keeper policy. Reverts while execution or withdrawals are halted for limit orders.
func ExecuteOrder(cur realm, orderID uint64, maxAmountIn int64, poolFee uint32, sqrtPriceLimitX96 string) (int64, int64) {
	return getImplementation().ExecuteOrder(0, cur, orderID, maxAmountIn, poolFee, sqrtPriceLimitX96)
}

// CollectPendingExecutionFee forwards fees pending for tokenPath to the protocol
// fee realm without another fill. Anyone may call it; the caller receives nothing.
// Returns the amount forwarded and the amount left pending.
// Reverts while withdrawals are halted for Limit orders.
func CollectPendingExecutionFee(cur realm, tokenPath string) (int64, int64) {
	collector, ok := getImplementation().(pendingExecutionFeeCollector)
	if !ok {
		panic(errImplDoesNotSupportFeeCollection)
	}

	return collector.CollectPendingExecutionFee(0, cur, tokenPath)
}

// CleanupExpiredOrders refunds pending orders after their deadline.
// Anyone may call it.
//
// One call examines at most min(maxOrders, maxCleanupBatchSize) orders after
// startAfterOrderID, in ID order. It returns the number of orders expired and
// the cursor for the next call; repeat until the cursor is 0.
// Reverts while withdrawals are halted for limit orders.
func CleanupExpiredOrders(cur realm, startAfterOrderID uint64, maxOrders int) (int, uint64) {
	return getImplementation().CleanupExpiredOrders(0, cur, startAfterOrderID, maxOrders)
}

// CleanupExpiredOrdersByIDs refunds only the named expired orders.
// orderIDs is a strictly increasing comma-separated list of positive decimal
// order IDs. Existing unexpired or underfunded orders are returned for retry.
// Reverts while withdrawals are halted for limit orders.
func CleanupExpiredOrdersByIDs(cur realm, orderIDs string) (int, string) {
	cleanup, ok := getImplementation().(expiredOrderCleanup)
	if !ok {
		panic(errImplDoesNotSupportTargetedCleanup)
	}

	return cleanup.CleanupExpiredOrdersByIDs(0, cur, orderIDs)
}

// SetExecutionFeeRate sets the execution fee rate snapshotted into new orders,
// in basis points of gross output.
// Admin or governance only.
func SetExecutionFeeRate(cur realm, executionFeeRate int64) {
	getImplementation().SetExecutionFeeRate(0, cur, executionFeeRate)
}

// SetMinMakingAmount sets the minimum input amount for new orders, in raw token units.
// Existing orders are unaffected. Admin or governance only.
func SetMinMakingAmount(cur realm, minMakingAmount int64) {
	getImplementation().SetMinMakingAmount(0, cur, minMakingAmount)
}

// SetOrderDeadlines sets the allowed order duration range for new orders,
// in seconds. Admin or governance only.
func SetOrderDeadlines(cur realm, minDuration int64, maxDuration int64) {
	getImplementation().SetOrderDeadlines(0, cur, minDuration, maxDuration)
}

// SetMaxCleanupBatchSize caps the orders one CleanupExpiredOrders call examines,
// bounding its gas. Admin or governance only.
func SetMaxCleanupBatchSize(cur realm, maxCleanupBatchSize int64) {
	getImplementation().SetMaxCleanupBatchSize(0, cur, maxCleanupBatchSize)
}

// SetMaxSlippageBps sets the slippage cap for new orders in [0, 10000] bps.
// Existing orders keep their slippage. Admin or governance only.
func SetMaxSlippageBps(cur realm, maxSlippageBps int64) {
	getImplementation().SetMaxSlippageBps(0, cur, maxSlippageBps)
}

package limit

import (
	_ "gno.land/r/gnoswap/rbac/v1" // registers the roles read through access

	"errors"

	plimit "gno.land/p/gnoswap/order/limit/v0"
	"gno.land/p/gnoswap/store/v1"
	"gno.land/p/gnoswap/version_manager/v1"
)

var (
	currentAddress address
	kvStore        store.KVStore

	versionManager version_manager.VersionManager
	implementation plimit.ILimitOrder
)

func init(cur realm) {
	currentAddress = cur.Address()
	kvStore = store.NewKVStore(currentAddress)

	versionManager = version_manager.NewVersionManager(
		cur.PkgPath(),
		kvStore,
		initializeDomainStore,
	)

	implementation = nil
}

func initializeDomainStore(_ int, _ realm, kvStore store.KVStore) any {
	return NewLimitOrderStore(kvStore)
}

// Address returns the realm address that escrows order funds.
// Users approve it before CreateOrder.
func Address() address {
	return currentAddress
}

func getImplementation() plimit.ILimitOrder {
	if implementation == nil {
		panic(errImplNotInitialized)
	}

	return implementation
}

func updateImplementation() error {
	result := versionManager.GetCurrentImplementation()
	if result == nil {
		return errors.New(errImplNotInitialized)
	}

	impl, ok := result.(plimit.ILimitOrder)
	if !ok {
		return errors.New(errInvalidImpl)
	}

	implementation = impl

	return nil
}

package limit

import (
	"errors"

	plimit "gno.land/p/gnoswap/order/limit/v0"
	"gno.land/p/gnoswap/store/v1"
	bptree "gno.land/p/nt/bptree/v0"
	ufmt "gno.land/p/nt/ufmt/v0"
)

// NewBPTreeN allocates an empty B+tree in the order/limit realm.
// Implementations create the store trees through it,
// so the trees are owned by the realm that stores them.
func NewBPTreeN(fanout int) *bptree.BPTree {
	return bptree.NewBPTreeN(fanout)
}

// StoreKey is a key of the limit order KV store.
type StoreKey string

func (s StoreKey) String() string {
	return string(s)
}

// Store layout. Tree keys are built by the plimit key helpers.
//
//	orders         OrderKey -> *Order, pending orders only
//	ordersByOwner  OwnerOrderKey -> orderID, pending orders only
//	pendingExecutionFees tokenPath -> int64, held until the protocol fee collector accepts them
//	nextOrderID    uint64
//	config         *Config
const (
	StoreKeyOrders               StoreKey = "orders"
	StoreKeyOrdersByOwner        StoreKey = "ordersByOwner"
	StoreKeyPendingExecutionFees StoreKey = "pendingExecutionFees"
	StoreKeyNextOrderID          StoreKey = "nextOrderID"
	StoreKeyConfig               StoreKey = "config"
)

type limitOrderStore struct {
	kvStore store.KVStore
}

// NewLimitOrderStore wraps the domain KV store.
func NewLimitOrderStore(kvStore store.KVStore) plimit.ILimitOrderStore {
	return &limitOrderStore{kvStore: kvStore}
}

// set writes key after checking that rlm is the current realm.
// The KV store additionally enforces its write ACL for code realms.
func (s *limitOrderStore) set(_ int, rlm realm, key string, value any) error {
	if !rlm.IsCurrent() {
		return errors.New(ErrSpoofedRealm)
	}

	return s.kvStore.Set(0, rlm, key, value)
}

func (s *limitOrderStore) getTree(key StoreKey) *bptree.BPTree {
	tree, err := s.kvStore.GetBPTree(key.String())
	if err != nil {
		panic(err.Error())
	}

	if tree == nil {
		panic(ufmt.Sprintf(errNilValue, key.String()))
	}

	return tree
}

func (s *limitOrderStore) setTree(_ int, rlm realm, key StoreKey, tree *bptree.BPTree) error {
	if !rlm.IsCurrent() {
		return errors.New(ErrSpoofedRealm)
	}

	if tree == nil {
		return ufmt.Errorf(errNilValue, key.String())
	}

	return s.kvStore.Set(0, rlm, key.String(), tree)
}

func (s *limitOrderStore) HasOrders() bool { return s.kvStore.Has(StoreKeyOrders.String()) }

func (s *limitOrderStore) GetOrders() *bptree.BPTree { return s.getTree(StoreKeyOrders) }

func (s *limitOrderStore) SetOrders(_ int, rlm realm, orders *bptree.BPTree) error {
	return s.setTree(0, rlm, StoreKeyOrders, orders)
}

func (s *limitOrderStore) HasOrdersByOwner() bool {
	return s.kvStore.Has(StoreKeyOrdersByOwner.String())
}

func (s *limitOrderStore) GetOrdersByOwner() *bptree.BPTree {
	return s.getTree(StoreKeyOrdersByOwner)
}

func (s *limitOrderStore) SetOrdersByOwner(_ int, rlm realm, ordersByOwner *bptree.BPTree) error {
	return s.setTree(0, rlm, StoreKeyOrdersByOwner, ordersByOwner)
}

func (s *limitOrderStore) HasPendingExecutionFees() bool {
	return s.kvStore.Has(StoreKeyPendingExecutionFees.String())
}

func (s *limitOrderStore) GetPendingExecutionFees() *bptree.BPTree {
	return s.getTree(StoreKeyPendingExecutionFees)
}

func (s *limitOrderStore) SetPendingExecutionFees(_ int, rlm realm, pendingExecutionFees *bptree.BPTree) error {
	return s.setTree(0, rlm, StoreKeyPendingExecutionFees, pendingExecutionFees)
}

func (s *limitOrderStore) HasNextOrderID() bool {
	return s.kvStore.Has(StoreKeyNextOrderID.String())
}

func (s *limitOrderStore) GetNextOrderID() uint64 {
	id, err := s.kvStore.GetUint64(StoreKeyNextOrderID.String())
	if err != nil {
		panic(err.Error())
	}

	return id
}

func (s *limitOrderStore) SetNextOrderID(_ int, rlm realm, id uint64) error {
	return s.set(0, rlm, StoreKeyNextOrderID.String(), id)
}

func (s *limitOrderStore) HasConfig() bool { return s.kvStore.Has(StoreKeyConfig.String()) }

func (s *limitOrderStore) GetConfig() *plimit.Config {
	result, err := s.kvStore.Get(StoreKeyConfig.String())
	if err != nil {
		panic(err.Error())
	}

	config, ok := result.(*plimit.Config)
	if !ok || config == nil {
		panic(ufmt.Sprintf(errInvalidConfigType, result))
	}

	return config
}

func (s *limitOrderStore) SetConfig(_ int, rlm realm, config *plimit.Config) error {
	if !rlm.IsCurrent() {
		return errors.New(ErrSpoofedRealm)
	}

	if config == nil {
		return errors.New(errNilConfig)
	}

	return s.kvStore.Set(0, rlm, StoreKeyConfig.String(), config)
}

package limit

import (
	"errors"

	prbac "gno.land/p/gnoswap/rbac/v1"
	"gno.land/r/gnoswap/access/v1"
	"gno.land/r/gnoswap/common"
	"gno.land/r/gnoswap/pool"
)

// NewSwapCallback binds payment to this proxy's custody, the order's input
// token and its input budget. Only code already executing in the proxy's current
// realm context can create it. The closure is declared here so pool callbacks
// retain proxy custody rather than paying from an implementation realm.
func NewSwapCallback(_ int, rlm realm, tokenIn string, zeroForOne bool, maxAmountIn int64) func(cur realm, amount0Delta, amount1Delta int64, marker *pool.CallbackMarker) error {
	if !rlm.IsCurrent() || rlm.Address() != Address() || tokenIn == "" || maxAmountIn <= 0 {
		panic(errInvalidSwapCallback)
	}

	poolAddress := access.MustGetAddress(prbac.ROLE_POOL.String())
	remaining := maxAmountIn

	return func(cur realm, amount0Delta, amount1Delta int64, marker *pool.CallbackMarker) error {
		if !cur.IsCurrent() || cur.Address() != Address() || cur.Previous().Address() != poolAddress || marker == nil {
			return errors.New(errInvalidSwapCallback)
		}

		input, output := amount0Delta, amount1Delta
		if !zeroForOne {
			input, output = amount1Delta, amount0Delta
		}

		if input <= 0 || output > 0 || input > remaining {
			return errors.New(errInvalidSwapCallback)
		}

		remaining -= input

		return common.Transfer(0, cur, tokenIn, poolAddress, input)
	}
}

package limit

import (
	plimit "gno.land/p/gnoswap/order/limit/v0"

	"gno.land/r/gnoswap/access/v1"
)

// RegisterInitializer registers an implementation version.
// Each version calls it from init with a factory that receives the shared store.
// Only packages under this realm's path may register,
// and the first registration becomes active.
// A nil initializer is rejected before its version path is registered.
func RegisterInitializer(cur realm, initializer func(_ int, rlm realm, orderStore plimit.ILimitOrderStore) plimit.ILimitOrder) {
	if initializer == nil {
		panic(ErrNilInitializer)
	}

	initializerFunc := func(_ int, rlm realm, domainStore any) any {
		access.AssertIsRlmCurrent(0, rlm)

		orderStore, ok := domainStore.(plimit.ILimitOrderStore)
		if !ok {
			panic(errInvalidDomainStore)
		}

		return initializer(0, rlm, orderStore)
	}

	err := versionManager.RegisterInitializer(0, cur, initializerFunc)
	if err != nil {
		panic(err.Error())
	}

	err = updateImplementation()
	if err != nil {
		panic(err.Error())
	}
}

// UpgradeImpl activates a previously registered version by package path.
// Admin or governance only.
func UpgradeImpl(cur realm, packagePath string) {
	caller := cur.Previous().Address()
	access.AssertIsAdminOrGovernance(caller)

	err := versionManager.ChangeImplementation(0, cur, packagePath)
	if err != nil {
		panic(err.Error())
	}

	err = updateImplementation()
	if err != nil {
		panic(err.Error())
	}
}

// GetImplementationPackagePath returns the active implementation path.
func GetImplementationPackagePath() string {
	return versionManager.GetCurrentPackagePath()
}

package impl

import (
	"gno.land/p/gnoswap/order/access/manager/v0"
	pdca "gno.land/p/gnoswap/order/dca/v0"
	prbac "gno.land/p/gnoswap/rbac/v1"
	bptree "gno.land/p/nt/bptree/v0"
	ufmt "gno.land/p/nt/ufmt/v0"

	"gno.land/r/gnoswap/access/v1"
	"gno.land/r/gnoswap/common"
	"gno.land/r/gnoswap/order/halt"
	"gno.land/r/gnoswap/order/keeper"
	"gno.land/r/gnoswap/order/whitelist"
)

// assertIsAdminCall runs the checks shared by admin entry points
// and returns the calling realm.
func (d *dcaOrderImpl) assertIsAdminCall(_ int, rlm realm) realm {
	access.AssertIsRlmCurrent(0, rlm)
	common.AssertIsNotHandleNativeCoin()
	d.assertIsNotExecuting()

	prev := rlm.Previous()
	access.AssertIsAdminOrGovernance(prev.Address())

	return prev
}

// assertIsNotExecuting rejects re-entry from the swap
// into any state-changing entry point.
func (d *dcaOrderImpl) assertIsNotExecuting() {
	if d.store.IsExecuting() {
		panic(makeErrorWithDetails(errReentrant, "group execution in progress").Error())
	}
}

// assertIsNotHalted rejects the call while any of operations is halted
// for DCA orders in gno.land/r/gnoswap/order/halt.
func assertIsNotHalted(operations ...string) {
	if operation, halted := haltedOperation(operations...); halted {
		panic(makeErrorWithDetails(errHalted, ufmt.Sprintf("operation(%s)", operation)).Error())
	}
}

// haltedOperation returns the first of operations halted for DCA orders.
func haltedOperation(operations ...string) (string, bool) {
	for _, operation := range operations {
		if halt.IsHalted(halt.TargetDCA, operation) {
			return operation, true
		}
	}

	return "", false
}

// assertIsAuthorizedKeeper rejects callers that gno.land/r/gnoswap/order/keeper
// does not allow to run rounds on target, the DCA proxy package path.
// ExecuteGroup is assigned to DCAKeeperRole at deployment; admin or
// governance grants it to keepers or reassigns the selector.
func assertIsAuthorizedKeeper(target string, caller address) {
	if !keeper.IsAuthorized(target, keeper.SelectorExecuteGroup, caller) {
		panic(makeErrorWithDetails(errNotKeeper, ufmt.Sprintf("caller(%s)", caller.String())).Error())
	}
}

// assertIsManagerCall runs the checks shared by the manager entry points
// (token minimums and pair price limits) and returns the calling realm.
// Admin and governance may always call them; other callers need the
// PoolManagerRole that gno.land/r/gnoswap/order/keeper assigns on the DCA
// proxy package path.
func (d *dcaOrderImpl) assertIsManagerCall(_ int, rlm realm, selector manager.Selector) realm {
	access.AssertIsRlmCurrent(0, rlm)
	common.AssertIsNotHandleNativeCoin()
	d.assertIsNotExecuting()

	prev := rlm.Previous()
	caller := prev.Address()

	if isAdminOrGovernance(caller) || keeper.IsAuthorized(rlm.PkgPath(), selector, caller) {
		return prev
	}

	panic(makeErrorWithDetails(errNotKeeper, ufmt.Sprintf("caller(%s) selector(%s)", caller.String(), string(selector))).Error())
}

// isAdminOrGovernance reports whether caller is the GnoSwap admin or governance.
func isAdminOrGovernance(caller address) bool {
	return access.IsAuthorized(prbac.ROLE_ADMIN.String(), caller) || access.IsAuthorized(prbac.ROLE_GOVERNANCE.String(), caller)
}

// assertIsValidPair checks that inputToken and outputToken differ
// and that at least one whitelisted direct pool connects them.
func assertIsValidPair(inputToken string, outputToken string) {
	if inputToken == outputToken {
		panic(makeErrorWithDetails(errInvalidToken, ufmt.Sprintf("inputToken and outputToken are both %s", inputToken)).Error())
	}

	if !whitelist.HasWhitelistedPool(whitelist.TargetDCA, inputToken, outputToken) {
		panic(makeErrorWithDetails(errInvalidPool, ufmt.Sprintf("no whitelisted pool for %s -> %s", inputToken, outputToken)).Error())
	}
}

// assertHasPairPriceLimit checks that the pair direction has a price limit,
// without which its rounds cannot trade.
func assertHasPairPriceLimit(pairPriceLimits *bptree.BPTree, inputToken string, outputToken string) {
	if getPairPriceLimit(pairPriceLimits, inputToken, outputToken) == nil {
		panic(makeErrorWithDetails(errMissingPriceLimit, ufmt.Sprintf("no price limit for %s -> %s", inputToken, outputToken)).Error())
	}
}

// assertIsAllowedInterval checks that new orders may use interval.
func assertIsAllowedInterval(config *pdca.Config, interval int64) {
	if !config.IsAllowedInterval(interval) {
		panic(makeErrorWithDetails(errInvalidInterval, ufmt.Sprintf("interval(%d)", interval)).Error())
	}
}

// assertIsAllowedSlot checks that new orders may use slotOffset at interval.
func assertIsAllowedSlot(config *pdca.Config, interval int64, slotOffset int64) {
	if !config.IsAllowedSlot(interval, slotOffset) {
		panic(makeErrorWithDetails(
			errInvalidSlotOffset,
			ufmt.Sprintf("slotOffset(%d) must be a multiple of %d in [0, %d)", slotOffset, config.SlotStep(interval), interval),
		).Error())
	}
}

// assertIsValidOrderSize checks the order against the configured limits;
// minAmountPerExecution is the effective minimum of the input token
// (see minAmountPerExecution).
func assertIsValidOrderSize(config *pdca.Config, minAmountPerExecution int64, amountPerExecution int64, executionCount int64) {
	if amountPerExecution < minAmountPerExecution {
		panic(makeErrorWithDetails(
			errInvalidAmount,
			ufmt.Sprintf("amountPerExecution(%d) must be >= %d", amountPerExecution, minAmountPerExecution),
		).Error())
	}

	if executionCount <= 0 || executionCount > config.MaxExecutionCount() {
		panic(makeErrorWithDetails(
			errInvalidExecutionCount,
			ufmt.Sprintf("executionCount(%d) must be in [1, %d]", executionCount, config.MaxExecutionCount()),
		).Error())
	}
}

// assertIsOrderOwner checks that caller owns the order.
func assertIsOrderOwner(order *pdca.Order, caller address) {
	if order.Owner() != caller {
		panic(makeErrorWithDetails(errNotOrderOwner, ufmt.Sprintf("orderId(%d)", order.ID())).Error())
	}
}

// assertIsQuotedAmountIn checks that the round sells the input
// amountOutMin was quoted for.
// A floor quoted for a larger input would keep that trade's price impact,
// which is looser than the smaller round needs, so a changed orderAmount
// needs a new quote instead of a rescaled floor.
// Passing 0 for both skips the check.
func assertIsQuotedAmountIn(group *pdca.Group, expectedAmountIn int64, amountOutMin int64) {
	if expectedAmountIn == 0 && amountOutMin == 0 {
		return
	}

	if expectedAmountIn != group.OrderAmount() {
		panic(makeErrorWithDetails(
			errAmountInMismatch,
			ufmt.Sprintf("groupId(%s) expectedAmountIn(%d) orderAmount(%d)", group.ID(), expectedAmountIn, group.OrderAmount()),
		).Error())
	}
}

package impl

import (
	"gno.land/p/gnoswap/gnsmath/v1"
	pdca "gno.land/p/gnoswap/order/dca/v0"
	ufmt "gno.land/p/nt/ufmt/v0"

	"gno.land/r/gnoswap/access/v1"
	"gno.land/r/gnoswap/common"
	"gno.land/r/gnoswap/order/halt"
)

// ClaimGroupOrders pays accrued output to the owners of a group's active
// orders, like Claim, so owners receive output without claiming.
// Anyone may call it; output always goes to the order owner.
//
// The call releases each examined order's execution logs whose rounds all executed
// and deletes finished orders. The freed storage deposit is refunded to the
// caller, a fixed reward per log of three executed rounds.
//
// One call examines at most min(maxOrderCount, maxClaimBatchSize) orders
// after startAfterOrderID, in ID order, so its gas stays bounded.
// The returned cursor is the last examined order ID; pass it back until it
// is 0. New orders get higher IDs and finished orders leave the index,
// so changes between calls neither skip nor repeat an order.
func (d *dcaOrderImpl) ClaimGroupOrders(_ int, rlm realm, groupID string, startAfterOrderID uint64, maxOrderCount int) (int, uint64) {
	access.AssertIsRlmCurrent(0, rlm)
	common.AssertIsNotHandleNativeCoin()
	assertIsNotHalted(halt.OperationWithdraw)
	d.assertIsNotExecuting()

	if maxOrderCount <= 0 {
		panic(makeErrorWithDetails(errInvalidAmount, ufmt.Sprintf("maxOrderCount(%d) must be positive", maxOrderCount)).Error())
	}

	group, err := d.getGroup(groupID)
	if err != nil {
		panic(err.Error())
	}

	prev := rlm.Previous()

	result, err := d.claimGroupOrders(0, rlm, prev.Address(), prev.PkgPath(), group, startAfterOrderID, maxOrderCount)
	if err != nil {
		panic(err.Error())
	}

	emitGroupOrdersClaimed(
		prev.Address(),
		prev.PkgPath(),
		groupID,
		result.examinedOrderCount,
		result.claimedOrderCount,
		result.releasedExecutionLogCount,
		result.nextCursor,
	)

	emitPayoutExecutionFee(prev.Address(), prev.PkgPath(), group, result.executionFeeAmount, d.pendingExecutionFeeAmount(group.OutputToken()))

	return result.claimedOrderCount, result.nextCursor
}

// groupOrdersClaimResult describes one page of claimGroupOrders.
type groupOrdersClaimResult struct {
	examinedOrderCount        int
	claimedOrderCount         int    // orders paid or completed
	releasedExecutionLogCount int64  // order logs freed for the caller
	executionFeeAmount        int64  // execution fee the payouts kept as pending
	nextCursor                uint64 // last examined order ID, 0 when the group is done
}

// claimGroupOrders claims one page of the group's orders.
func (d *dcaOrderImpl) claimGroupOrders(
	_ int,
	rlm realm,
	prevAddr address,
	prevRealm string,
	group *pdca.Group,
	startAfterOrderID uint64,
	maxOrderCount int,
) (groupOrdersClaimResult, error) {
	limit := int64(maxOrderCount)
	if maxClaimBatchSize := d.store.GetConfig().MaxClaimBatchSize(); limit > maxClaimBatchSize {
		limit = maxClaimBatchSize
	}

	orderIDs, hasMore := d.getGroupOrderIDs(group.ID(), startAfterOrderID, int(limit))

	result := groupOrdersClaimResult{examinedOrderCount: len(orderIDs)}
	for _, orderID := range orderIDs {
		order, err := d.getOrder(orderID)
		if err != nil {
			return groupOrdersClaimResult{}, err
		}

		payout, releasedCount, isUpdated, err := d.claimOrder(0, rlm, prevAddr, prevRealm, order, group)
		if err != nil {
			return groupOrdersClaimResult{}, err
		}

		result.executionFeeAmount = gnsmath.SafeAddInt64(result.executionFeeAmount, payout.executionFeeAmount)

		result.releasedExecutionLogCount = gnsmath.SafeAddInt64(result.releasedExecutionLogCount, releasedCount)

		if isUpdated {
			result.claimedOrderCount++
		}
	}

	if hasMore {
		result.nextCursor = orderIDs[len(orderIDs)-1]
	}

	return result, nil
}

// getGroupOrderIDs returns up to count active order IDs of a group after
// startAfterID, and whether more remain. IDs are collected before any
// order is claimed, since a claim may remove entries from the index.
func (d *dcaOrderImpl) getGroupOrderIDs(groupID string, startAfterID uint64, count int) ([]uint64, bool) {
	if startAfterID == ^uint64(0) {
		return nil, false
	}

	prefix := pdca.GroupOrderPrefix(groupID)
	start := pdca.GroupOrderKey(groupID, gnsmath.SafeAddUint64(startAfterID, 1))

	orderIDs := []uint64{}
	hasMore := false

	d.store.GetOrdersByGroup().Iterate(start, pdca.PrefixEnd(prefix), func(_ string, value any) bool {
		if len(orderIDs) == count {
			hasMore = true
			return true
		}

		orderIDs = append(orderIDs, value.(uint64))

		return false
	})

	return orderIDs, hasMore
}

package impl

import (
	pdca "gno.land/p/gnoswap/order/dca/v0"
	ufmt "gno.land/p/nt/ufmt/v0"
)

// SetOrderLimits sets the minimum input per execution
// and the maximum executions per order.
// Existing orders are unaffected. Admin or governance only.
func (d *dcaOrderImpl) SetOrderLimits(_ int, rlm realm, minAmountPerExecution int64, maxExecutionCount int64) {
	prev := d.assertIsAdminCall(0, rlm)

	if minAmountPerExecution <= 0 {
		panic(makeErrorWithDetails(
			errInvalidConfig,
			ufmt.Sprintf("minAmountPerExecution(%d) must be positive", minAmountPerExecution),
		).Error())
	}

	if maxExecutionCount <= 0 || maxExecutionCount > maxExecutionCountLimit {
		panic(makeErrorWithDetails(
			errInvalidConfig,
			ufmt.Sprintf("maxExecutionCount(%d) must be in [1, %d]", maxExecutionCount, maxExecutionCountLimit),
		).Error())
	}

	config := d.store.GetConfig()
	previousMinAmountPerExecution := config.MinAmountPerExecution()
	previousMaxExecutionCount := config.MaxExecutionCount()
	config.SetMinAmountPerExecution(minAmountPerExecution)
	config.SetMaxExecutionCount(maxExecutionCount)

	emitConfigUpdated(prev.Address(), prev.PkgPath(), "minAmountPerExecution", previousMinAmountPerExecution, minAmountPerExecution)
	emitConfigUpdated(prev.Address(), prev.PkgPath(), "maxExecutionCount", previousMaxExecutionCount, maxExecutionCount)
}

// AddAllowedInterval allows new orders to use interval.
// Admin or governance only.
func (d *dcaOrderImpl) AddAllowedInterval(_ int, rlm realm, interval int64) {
	prev := d.assertIsAdminCall(0, rlm)

	if interval < minAllowedInterval || interval > maxAllowedInterval {
		panic(makeErrorWithDetails(
			errInvalidInterval,
			ufmt.Sprintf("interval(%d) must be in [%d, %d]", interval, minAllowedInterval, maxAllowedInterval),
		).Error())
	}

	if err := d.store.GetConfig().AddAllowedInterval(interval); err != nil {
		panic(makeErrorWithDetails(errInvalidInterval, ufmt.Sprintf("interval(%d): %s", interval, err.Error())).Error())
	}

	emitAllowedIntervalUpdated(prev.Address(), prev.PkgPath(), interval, true)
}

// RemoveAllowedInterval stops new orders from using interval.
// Existing orders and groups of that interval keep running.
// At least one interval must stay allowed. Admin or governance only.
func (d *dcaOrderImpl) RemoveAllowedInterval(_ int, rlm realm, interval int64) {
	prev := d.assertIsAdminCall(0, rlm)

	config := d.store.GetConfig()
	if len(config.AllowedIntervals()) == 1 && config.IsAllowedInterval(interval) {
		panic(makeErrorWithDetails(errInvalidConfig, "at least one interval must stay allowed").Error())
	}

	if err := config.RemoveAllowedInterval(interval); err != nil {
		panic(makeErrorWithDetails(errInvalidInterval, ufmt.Sprintf("interval(%d): %s", interval, err.Error())).Error())
	}

	emitAllowedIntervalUpdated(prev.Address(), prev.PkgPath(), interval, false)
}

// SetMinExecutionGapRate sets the minimum gap between a group's executions,
// in basis points of its interval. Admin or governance only.
func (d *dcaOrderImpl) SetMinExecutionGapRate(_ int, rlm realm, minExecutionGapRate int64) {
	prev := d.assertIsAdminCall(0, rlm)

	if minExecutionGapRate < 0 || minExecutionGapRate > pdca.BasisPointDenominator {
		panic(makeErrorWithDetails(
			errInvalidConfig,
			ufmt.Sprintf("minExecutionGapRate(%d) must be in [0, %d]", minExecutionGapRate, pdca.BasisPointDenominator),
		).Error())
	}

	config := d.store.GetConfig()
	previousMinExecutionGapRate := config.MinExecutionGapRate()
	config.SetMinExecutionGapRate(minExecutionGapRate)

	emitConfigUpdated(prev.Address(), prev.PkgPath(), "minExecutionGapRate", previousMinExecutionGapRate, minExecutionGapRate)
}

// SetMaxPoolPriceDeviationRate sets how far, in basis points of price, a pool's
// price may sit on the favorable side of its swap price limit and still be
// quoted (0 to 10000; 0 disables the check). Admin or governance only.
func (d *dcaOrderImpl) SetMaxPoolPriceDeviationRate(_ int, rlm realm, maxPoolPriceDeviationRate int64) {
	prev := d.assertIsAdminCall(0, rlm)

	if maxPoolPriceDeviationRate < 0 || maxPoolPriceDeviationRate > pdca.BasisPointDenominator {
		panic(makeErrorWithDetails(
			errInvalidConfig,
			ufmt.Sprintf("maxPoolPriceDeviationRate(%d) must be in [0, %d]", maxPoolPriceDeviationRate, pdca.BasisPointDenominator),
		).Error())
	}

	config := d.store.GetConfig()
	previousMaxPoolPriceDeviationRate := config.MaxPoolPriceDeviationRate()
	config.SetMaxPoolPriceDeviationRate(maxPoolPriceDeviationRate)

	emitConfigUpdated(
		prev.Address(),
		prev.PkgPath(),
		"maxPoolPriceDeviationRate",
		previousMaxPoolPriceDeviationRate,
		maxPoolPriceDeviationRate,
	)
}

// SetMaxPairPriceLimitAge sets how long, in seconds, a pair price limit stays
// usable after the pool manager set it (60 to 604800). A quote or round under
// an older limit finds no eligible pool, so rounds stop when the manager stops
// refreshing limits instead of trading at a stale price. Admin or governance only.
func (d *dcaOrderImpl) SetMaxPairPriceLimitAge(_ int, rlm realm, maxPairPriceLimitAge int64) {
	prev := d.assertIsAdminCall(0, rlm)

	if maxPairPriceLimitAge < minMaxPairPriceLimitAge || maxPairPriceLimitAge > maxMaxPairPriceLimitAge {
		panic(makeErrorWithDetails(
			errInvalidConfig,
			ufmt.Sprintf("maxPairPriceLimitAge(%d) must be in [%d, %d]", maxPairPriceLimitAge, minMaxPairPriceLimitAge, maxMaxPairPriceLimitAge),
		).Error())
	}

	config := d.store.GetConfig()
	previousMaxPairPriceLimitAge := config.MaxPairPriceLimitAge()
	config.SetMaxPairPriceLimitAge(maxPairPriceLimitAge)

	emitConfigUpdated(prev.Address(), prev.PkgPath(), "maxPairPriceLimitAge", previousMaxPairPriceLimitAge, maxPairPriceLimitAge)
}

// SetMaxClaimBatchSize caps the orders one ClaimGroupOrders call examines.
// Admin or governance only.
func (d *dcaOrderImpl) SetMaxClaimBatchSize(_ int, rlm realm, maxClaimBatchSize int64) {
	prev := d.assertIsAdminCall(0, rlm)

	if maxClaimBatchSize <= 0 || maxClaimBatchSize > maxClaimBatchSizeLimit {
		panic(makeErrorWithDetails(
			errInvalidConfig,
			ufmt.Sprintf("maxClaimBatchSize(%d) must be in [1, %d]", maxClaimBatchSize, maxClaimBatchSizeLimit),
		).Error())
	}

	config := d.store.GetConfig()
	previousMaxClaimBatchSize := config.MaxClaimBatchSize()
	config.SetMaxClaimBatchSize(maxClaimBatchSize)

	emitConfigUpdated(prev.Address(), prev.PkgPath(), "maxClaimBatchSize", previousMaxClaimBatchSize, maxClaimBatchSize)
}

// SetSlotStep sets the spacing of the slot offsets new orders may use
// at interval. Existing groups keep their slot.
// Admin or governance only.
func (d *dcaOrderImpl) SetSlotStep(_ int, rlm realm, interval int64, slotStep int64) {
	prev := d.assertIsAdminCall(0, rlm)

	config := d.store.GetConfig()
	assertIsAllowedInterval(config, interval)
	previousSlotStep := config.SlotStep(interval)

	if err := config.SetSlotStep(interval, slotStep); err != nil {
		panic(makeErrorWithDetails(
			errInvalidSlotStep,
			ufmt.Sprintf("slotStep(%d) must be a positive divisor of interval(%d)", slotStep, interval),
		).Error())
	}

	emitSlotStepChanged(prev.Address(), prev.PkgPath(), interval, previousSlotStep, slotStep)
}

